from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class VMSInfov1(SchemaObject):
    vm_name = SchemaField(name="vm_name", optional=True)
    vm_r_id = SchemaField(name="vm_r_id", optional=True)
    availability_status = SchemaField(name="availability_status", optional=True)
    operational_state = SchemaField(name="operational_state", optional=True)
    sw_version = SchemaField(name="sw_version", optional=True)
    usage_state = SchemaField(name="usage_state", optional=True)

    def __init__(self, vm_name, vm_r_id, availability_status, operational_state, sw_version, usage_state):
        self.vm_name = vm_name
        self.vm_r_id = vm_r_id
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.sw_version = sw_version
        self.usage_state = usage_state

        super(VMSInfov1, self).__init__()
